  return landForm(
    {
      subjectKind: "message",
      subjectId: loaded.messageId,
      form: "tool_result_summary",
      content: "",
      metadata: { outcome: deriveToolOutcome({ isError: block["isError"] === true }) },
    },
    await run.provider.summarizeToolResult({
      toolName: pairedCall?.toolName ?? "unknown_tool",
      content,
    }),
